plugins\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-invariants\": {\n      \"optional\": true\n    }\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-theme\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"files\": [\n    \"lib\",\n    \"assets/qq2006\",\n    \"cordis.patch.yml\",\n    \"dsh.plugin.json\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"scripts\": {\n    \"build\": \"node scripts/build-client.mjs\",\n    \"prepare\": \"node scripts/build-client.mjs\",\n    \"validate\": \"node scripts/validate.mjs\",\n    \"test\": \"node scripts/validate.mjs\",\n    \"bundle\": \"node -e \\\"console.error('bundle runs inside the DSH monorepo (packages/client/ui-skin-qq2006); use npm run build to refresh lib/client.js')\\\"\"\n  }\n}\n"
